import{_ as e,o,c as r,ag as d}from"./chunks/framework.KxDd3USm.js";const u=JSON.parse('{"title":"11.1 五步解题法：不要从第一个空开始硬翻 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"11-专业英语/01-五步解题法.md","filePath":"11-专业英语/01-五步解题法.md"}'),s={name:"11-专业英语/01-五步解题法.md"};function n(a,t,c,i,l,g){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="_11-1-五步解题法-不要从第一个空开始硬翻-★★★" tabindex="-1">11.1 五步解题法：不要从第一个空开始硬翻 ★★★ <a class="header-anchor" href="#_11-1-五步解题法-不要从第一个空开始硬翻-★★★" aria-label="Permalink to &quot;11.1 五步解题法：不要从第一个空开始硬翻 ★★★&quot;">​</a></h1><h3 id="_1-1-第一步-扫读主题" tabindex="-1">1.1 第一步：扫读主题 <a class="header-anchor" href="#_1-1-第一步-扫读主题" aria-label="Permalink to &quot;1.1 第一步：扫读主题&quot;">​</a></h3><p>先用 20–30 秒读首句、末句和重复出现的名词，回答：“这段在讲什么？”</p><p>例如反复出现 <code>requirements, stakeholders, traceability, test cases</code>，主题大概率是<strong>需求工程</strong>；反复出现 <code>model, training data, prediction, overfitting</code>，主题就是<strong>机器学习</strong>。</p><p>知道主题后，大脑会自动缩小词义范围。<code>model</code> 在 AI 文章中通常是“模型”，在软件工程中也可能是“开发模型”，不能一看到就只译成“模特”。</p><h3 id="_1-2-第二步-先判词性-再看词义" tabindex="-1">1.2 第二步：先判词性，再看词义 <a class="header-anchor" href="#_1-2-第二步-先判词性-再看词义" aria-label="Permalink to &quot;1.2 第二步：先判词性，再看词义&quot;">​</a></h3><p>空格前后的结构会直接淘汰一半选项：</p><table tabindex="0"><thead><tr><th>线索</th><th>空格常需什么</th><th>例子</th></tr></thead><tbody><tr><td><code>a/an/the + ___</code></td><td>名词，或形容词+名词</td><td>an <strong>interface</strong></td></tr><tr><td><code>be + ___</code></td><td>形容词、过去分词或现在分词</td><td>is <strong>reliable</strong></td></tr><tr><td><code>to + ___</code></td><td>动词原形</td><td>to <strong>reduce</strong> cost</td></tr><tr><td><code>can/must/should + ___</code></td><td>动词原形</td><td>can <strong>detect</strong> errors</td></tr><tr><td><code>___ + noun</code></td><td>形容词或名词作定语</td><td><strong>secure</strong> channel</td></tr><tr><td><code>verb + ___</code></td><td>名词/代词作宾语，或副词修饰动词</td><td>improve <strong>quality</strong></td></tr><tr><td><code>one of the + ___</code></td><td>复数名词/最高级+复数名词</td><td>one of the <strong>methods</strong></td></tr></tbody></table><p><strong>反例前置</strong>：句子 <code>The system can ___ failures.</code> 中，若选项有 <code>detection</code>（名词）和 <code>detect</code>（动词），即使两个都认识，也只能选 <code>detect</code>。情态动词 <code>can</code> 后必须接动词原形。</p><h3 id="_1-3-第三步-检查固定搭配" tabindex="-1">1.3 第三步：检查固定搭配 <a class="header-anchor" href="#_1-3-第三步-检查固定搭配" aria-label="Permalink to &quot;1.3 第三步：检查固定搭配&quot;">​</a></h3><p>专业英语里很多答案不是“意思勉强通顺”就行，而是搭配固定：</p><table tabindex="0"><thead><tr><th>搭配</th><th>含义</th></tr></thead><tbody><tr><td>be responsible <strong>for</strong></td><td>对……负责</td></tr><tr><td>depend/rely <strong>on</strong></td><td>依赖</td></tr><tr><td>comply <strong>with</strong></td><td>遵守、符合</td></tr><tr><td>consist <strong>of</strong></td><td>由……组成</td></tr><tr><td>prevent A <strong>from</strong> doing B</td><td>防止 A 做 B</td></tr><tr><td>protect A <strong>from/against</strong> B</td><td>保护 A 免受 B</td></tr><tr><td>be divided <strong>into</strong></td><td>被分成</td></tr><tr><td>contribute <strong>to</strong></td><td>有助于、导致</td></tr><tr><td>result <strong>in</strong></td><td>导致某结果</td></tr><tr><td>result <strong>from</strong></td><td>由某原因引起</td></tr><tr><td>be compatible <strong>with</strong></td><td>与……兼容</td></tr><tr><td>have access <strong>to</strong></td><td>有权/能够访问</td></tr><tr><td>in terms <strong>of</strong></td><td>在……方面</td></tr><tr><td>rather <strong>than</strong></td><td>而不是</td></tr></tbody></table><p><strong>反例</strong>：<code>The failure results ___ data loss.</code> 应填 <code>in</code>，因为后面是结果；<code>Data loss results ___ the failure.</code> 才填 <code>from</code>，因为后面是原因。口诀：<strong>result in 去结果，result from 找来源</strong>。</p><h3 id="_1-4-第四步-寻找逻辑信号" tabindex="-1">1.4 第四步：寻找逻辑信号 <a class="header-anchor" href="#_1-4-第四步-寻找逻辑信号" aria-label="Permalink to &quot;1.4 第四步：寻找逻辑信号&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关系</th><th>常见信号词</th><th>做题动作</th></tr></thead><tbody><tr><td>转折</td><td>but, however, although, while, whereas</td><td>前后意思通常相反或对比</td></tr><tr><td>因果</td><td>because, since, therefore, thus, so, as a result</td><td>找原因与结果</td></tr><tr><td>递进</td><td>moreover, furthermore, in addition</td><td>后句延续同方向</td></tr><tr><td>举例</td><td>for example, such as, including</td><td>后面解释前面的类别</td></tr><tr><td>换言</td><td>in other words, that is</td><td>前后近义解释</td></tr><tr><td>条件</td><td>if, unless, provided that</td><td>判断条件成立与否</td></tr><tr><td>对照</td><td>rather than, instead of, on the other hand</td><td>排除相反项</td></tr></tbody></table><p>例：<code>The algorithm is accurate; however, it is computationally ___.</code> <code>however</code> 表示转折，前面夸“准确”，后面通常指出缺点，故应考虑 <code>expensive</code>（计算开销大），而不是 <code>efficient</code>。</p><h3 id="_1-5-第五步-代回全文-做三项检查" tabindex="-1">1.5 第五步：代回全文，做三项检查 <a class="header-anchor" href="#_1-5-第五步-代回全文-做三项检查" aria-label="Permalink to &quot;1.5 第五步：代回全文，做三项检查&quot;">​</a></h3><p>每空选完后，不要立刻交卷。把答案代回去检查：</p><ol><li>语法是否完整；</li><li>专业结论是否正确；</li><li>全段逻辑是否自洽。</li></ol><p>如果两个词都通顺，优先选能与上下文形成<strong>复现或照应</strong>的词。例如前文说 <code>users report problems quickly</code>，后文出现 <code>shortens the feedback ___</code>，通常选 <code>cycle</code>，因为快速报告问题会缩短反馈周期。</p><h3 id="_1-6-完整演示-把五步走完一整篇-5-空题" tabindex="-1">1.6 完整演示：把五步走完一整篇 5 空题 <a class="header-anchor" href="#_1-6-完整演示-把五步走完一整篇-5-空题" aria-label="Permalink to &quot;1.6 完整演示：把五步走完一整篇 5 空题&quot;">​</a></h3><blockquote><p>练习全篇：先自己试做下面这篇（不列选项先想一遍词性与意思），再对照&quot;思考痕迹&quot;。这篇同时也作为本课&quot;真题标杆&quot;短文的范本。</p></blockquote><p><strong>短文（主题：软件测试）</strong>：</p><blockquote><p>Software testing is the process of finding defects before software is delivered to users. A well-designed test case consists of input values, the environment in which they run, and the expected <strong>(1)</strong>, so that an actual result can be compared with it. Good test suites cover normal inputs as well as <strong>(2)</strong> cases, such as boundary values and invalid data. Because a defect discovered late is far more <strong>(3)</strong> to fix, testing is carried out throughout the life cycle instead of only at the end. Automated tests can be executed repeatedly at low cost, which is why teams keep a <strong>(4)</strong> test suite to ensure that recent changes do not <strong>(5)</strong> already-working behavior.</p></blockquote><p><strong>逐空思考痕迹（每一次动手前先背口诀：扫主题—判词性—看搭配—找逻辑—代回读）</strong>：</p><ul><li><strong>(1) A. output　B. quickly　C. implemented　D. removable</strong> 先判词性：<code>the expected ____</code>＝&quot;定冠词 + 形容词 + 空&quot;，所以空里应填<strong>名词</strong>。四个选项只有 <code>output</code>（输出结果）是名词；<code>quickly</code> 是副词、<code>implemented</code>/<code>removable</code> 都是分词/形容词。→ 选 <strong>A</strong>。</li><li><strong>(3) A. expensive　B. portable　C. automatic　D. shared</strong> 找逻辑：句首 <code>Because</code> 是因果信号，&quot;后期才发现的缺陷&quot;通常是<strong>修复成本更高</strong>，所以选 <code>expensive</code>（昂贵的）。它是形容词，也满足 <code>far more + 形容词 + to fix</code> 的结构。→ 选 <strong>A</strong>。</li><li><strong>(5) A. break　B. encrypt　C. compile　D. measure</strong> 判词性：<code>do not ____ already-working behavior</code>，情态/助动词 <code>do</code> 后应接<strong>动词原形</strong>；四个都能作动词原形，再看语义——&quot;确保最近改动不<strong>破坏</strong>已正常工作&quot;，<code>break</code>（破坏）最贴。→ 选 <strong>A</strong>。</li><li><strong>(2) A. unusual　B. encrypted　C. affordable　D. broken</strong> 先判词性：<code>____ cases</code> 是&quot;形容词 + 名词&quot;的结构，四个都能当形容词。这时<strong>不要硬猜词义，用逻辑与共现</strong>：<code>normal inputs as well as ____ cases, such as boundary values and invalid data</code>——<code>as well as</code> 表示加一种<strong>有别于正常</strong>的情况，后面举例&quot;边界值、非法数据&quot;，所以选 <code>unusual</code>（不寻常的）。<code>encrypted</code>（加密的）与测试用例边界无关，<code>affordable</code>/<code>broken</code> 均无该语境。→ 选 <strong>A</strong>。</li><li><strong>(4) A. regression　B. routing　C. symmetric　D. remote</strong><strong>这一步示范&quot;先跳过空&quot;</strong>：如果刚看完前几句一时判断不了，不要耗时间，先标号跳过，做完后面再回来。最后一句 <code>ensure that recent changes do not break already-working behavior</code>（确保近期改动不破坏已工作的行为），正是<strong>回归测试</strong>要防的事，固定术语是 <code>regression test suite</code>（回归测试套件）。其余 <code>routing</code>（路由）、<code>symmetric</code>（对称的）、<code>remote</code>（远程的）都无法与 test suite 组成此专业搭配。→ 回到 <strong>(4)</strong> 选 <strong>A</strong>。</li></ul><p><strong>代回检查</strong>：把 A、A、A、A、A 逐个代回读一遍——每空语法完整、专业结论正确、段落逻辑自洽（先讲测试目的→测试用例构成→覆盖正常与非常规→因因果强调尽早测试→自动化与回归）。五步收工。</p><p><strong>应试动作</strong>：(1)(2)(3) 靠<strong>判词性 + 找逻辑</strong>，(4) 靠<strong>搭配 + 先跳过 + 代回读</strong>，(5) 靠<strong>判词性</strong>。把它们分别标到这类题上，就能在两分钟内做完一组 5 空。</p><hr>',29)])])}const _=e(s,[["render",n]]);export{u as __pageData,_ as default};
